def carica_gusti(apps, schema_editor):
    Categoria = apps.get_model("novecento", "Categoria")
    Gruppo = apps.get_model("novecento", "Gruppo")
    Articolo = apps.get_model("novecento", "Articolo")
    categoria, _ = Categoria.objects.update_or_create(
        numero=8,
        defaults={
            "nome": "Gusti gelato in vaschetta",
            "nome_breve": "Gusti gelato",
            "descrizione": "Gusti crema e gusti frutta",
            "simbolo": "vaschetta",
        },
    )
    for ordine_gruppo, (nome_gruppo, gusti) in enumerate(GUSTI, start=1):
        gruppo, _ = Gruppo.objects.update_or_create(
            categoria=categoria, nome=nome_gruppo, defaults={"ordine": ordine_gruppo}
        )
        for ordine, gusto in enumerate(gusti, start=1):
            Articolo.objects.update_or_create(
                gruppo=gruppo, nome=gusto, defaults={"unita": "VS", "ordine": ordine}
            )


